import json
import mimetypes
import secrets
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse, parse_qs

ROOT = Path(__file__).resolve().parent
rooms = {}
lock = threading.Lock()


def snapshot(room):
    now = time.monotonic()
    room['members'] = {k: v for k, v in room['members'].items() if now - v < 12}
    return dict(playing=room['playing'], position=room['position'] +
                (now - room['updated'] if room['playing'] else 0),
                revision=room['revision'], members=len(room['members']))


class Handler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        pass

    def reply(self, status, data):
        body = json.dumps(data).encode()
        self.send_response(status)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('Cache-Control', 'no-store')
        self.end_headers()
        self.wfile.write(body)

    def do_POST(self):
        try:
            size = int(self.headers.get('Content-Length', 0))
            if size > 4096:
                return self.reply(413, {'error': '请求过大'})
            data = json.loads(self.rfile.read(size))
            action = self.path
            with lock:
                now = time.monotonic()
                for key in list(rooms):
                    if now - rooms[key]['active'] > 3600:
                        del rooms[key]
                if action == '/api/create':
                    code = ''.join(secrets.choice('23456789ABCDEFGHJKLMNPQRSTUVWXYZ') for _ in range(6))
                    while code in rooms:
                        code = secrets.token_hex(3).upper()
                    rooms[code] = dict(playing=False, position=0, updated=now,
                                       revision=0, members={}, active=now)
                else:
                    code = str(data.get('code', '')).strip().upper()
                room = rooms.get(code)
                if room is None:
                    return self.reply(404, {'error': '房间不存在，请检查房间码或重新创建。'})
                if action in ('/api/create', '/api/join'):
                    token = secrets.token_hex(16)
                    room['members'][token] = now
                    room['active'] = now
                    return self.reply(200, dict(code=code, token=token, **snapshot(room)))
                token = data.get('token')
                if token not in room['members']:
                    return self.reply(403, {'error': '连接已过期，请重新加入房间。'})
                room['members'][token] = now
                room['active'] = now
                if action == '/api/control':
                    position = float(data['position'])
                    if not 0 <= position <= 86400 or type(data['playing']) is not bool:
                        raise ValueError()
                    room.update(position=position, playing=data['playing'], updated=now,
                                revision=room['revision'] + 1)
                elif action == '/api/leave':
                    del room['members'][token]
                elif action != '/api/state':
                    return self.reply(404, {'error': '未知请求'})
                self.reply(200, snapshot(room))
        except (ValueError, KeyError, TypeError):
            self.reply(400, {'error': '请求格式不正确'})

    def do_GET(self):
        path = urlparse(self.path).path
        files = {'/': ROOT / 'web/index.html', '/app.js': ROOT / 'web/app.js',
                 '/style.css': ROOT / 'web/style.css', '/video.mp4': ROOT / 'inputs/演示.mp4'}
        file = files.get(path)
        if not file or not file.is_file():
            self.send_error(404)
            return
        size = file.stat().st_size
        start, end = 0, size - 1
        partial = self.headers.get('Range')
        if partial:
            try:
                unit, value = partial.split('=')
                a, b = value.split('-')
                if unit != 'bytes' or not a:
                    raise ValueError()
                start, end = int(a), min(int(b) if b else end, end)
                if start < 0 or start > end:
                    raise ValueError()
            except ValueError:
                self.send_response(416)
                self.send_header('Content-Range', f'bytes */{size}')
                self.end_headers()
                return
        self.send_response(206 if partial else 200)
        self.send_header('Content-Type', mimetypes.guess_type(file.name)[0] or 'application/octet-stream')
        self.send_header('Accept-Ranges', 'bytes')
        self.send_header('Content-Length', str(end - start + 1))
        if partial:
            self.send_header('Content-Range', f'bytes {start}-{end}/{size}')
        self.end_headers()
        try:
            with file.open('rb') as stream:
                stream.seek(start)
                remaining = end - start + 1
                while remaining:
                    chunk = stream.read(min(65536, remaining))
                    if not chunk:
                        break
                    self.wfile.write(chunk)
                    remaining -= len(chunk)
        except (ConnectionResetError, BrokenPipeError):
            pass


if __name__ == '__main__':
    print('一起看已启动：http://127.0.0.1:8765 （按 Ctrl+C 关闭）', flush=True)
    ThreadingHTTPServer(('127.0.0.1', 8765), Handler).serve_forever()

