const $ = id => document.getElementById(id);
const video = $('video');
let session = null, timer = null, busy = false, sending = false, generation = 0;
let latest = null, dragging = false;
function message(text) { $('message').textContent = text; }
async function api(action, data = {}) {
  const response = await fetch('/api/' + action, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(data), signal:AbortSignal.timeout(4000)});
  const result = await response.json();
  if (!response.ok) throw new Error(result.error);
  return result;
}
function renderTime() {
  const fmt = n => `${Math.floor((n || 0)/60).toString().padStart(2,'0')}:${Math.floor((n || 0)%60).toString().padStart(2,'0')}`;
  $('time').textContent = `${fmt(video.currentTime)} / ${fmt(video.duration)}`;
  $('seek').max = video.duration || 60;
  if (!dragging) $('seek').value = video.currentTime;
}
async function apply(state) {
  latest = state;
  $('connection').textContent = `已连接 · 房间内 ${state.members} 个窗口`;
  if (video.readyState < 1) return;
  const target = Math.min(state.position, video.duration || state.position);
  if (Math.abs(video.currentTime - target) > (state.playing ? 0.45 : 0.08)) video.currentTime = target;
  if (state.playing && target < video.duration) {
    if (video.paused) video.play().then(() => { $('toggle').textContent = '暂停'; }).catch(() => {
      if (latest?.playing) message('浏览器阻止了自动播放，请点击“播放”跟上房间。');
    });
  } else video.pause();
  $('toggle').textContent = video.paused ? '播放' : '暂停';
  renderTime();
}
async function enter(action) {
  $('create').disabled = true;
  try {
    session = await api(action, {code:$('code').value.trim()});
    generation++;
    $('lobby').hidden = true; $('room').hidden = false;
    $('roomcode').textContent = session.code;
    message('用另一个窗口打开此网页，输入上方房间码即可加入。');
    await apply(session);
    timer = setInterval(poll, 350);
  } catch (e) { message(e.message); }
  finally { $('create').disabled = false; }
}
async function poll() {
  if (!session || busy || sending) return;
  busy = true;
  const current = generation;
  try {
    const state = await api('state', session);
    if (current === generation && !sending) await apply(state);
  } catch (e) { if(session) { $('connection').textContent = '连接中断，正在重试…'; message(e.message); } }
  finally { busy = false; }
}
async function control(playing, position) {
  if (!session || sending) return;
  sending = true; generation++;
  try { await apply(await api('control', {...session, playing, position})); message(''); }
  catch(e) { message('操作未同步：' + e.message); }
  finally { sending = false; }
}
$('create').onclick = () => enter('create');
$('join').onsubmit = e => { e.preventDefault(); enter('join'); };
$('toggle').onclick = () => control(video.paused, video.currentTime >= video.duration ? 0 : video.currentTime);
$('seek').oninput = () => { dragging = true; };
$('seek').onchange = e => { dragging = false; control(latest?.playing || false, Number(e.target.value)); };
$('copy').onclick = async () => { try { await navigator.clipboard.writeText(session.code); message('房间码已复制。'); } catch { message('请手动复制房间码：' + session.code); } };
$('leave').onclick = () => {
  const old = session; session = null; generation++; clearInterval(timer); video.pause();
  api('leave',old).catch(()=>{}); $('room').hidden = true; $('lobby').hidden = false; message('已退出房间。');
};
$('fullscreen').onclick = () => $('room').requestFullscreen().catch(()=>message('当前浏览器不支持全屏。'));
video.onloadedmetadata = () => { renderTime(); if(latest && session) apply(latest); };
video.ontimeupdate = renderTime;
video.onended = () => { if(session && latest?.playing) control(false, video.duration); };
video.onerror = () => message('示例视频无法播放，请使用支持 MP4 的新版 Edge 或 Chrome。');
window.addEventListener('pagehide', () => { if(session) navigator.sendBeacon('/api/leave',new Blob([JSON.stringify(session)],{type:'application/json'})); });

