"""本机一起看：仅使用 Python 标准库。"""
import json
import mimetypes
import secrets
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse

ROOT = Path(__file__).resolve().parent
rooms = {}
lock = threading.Lock()


def snapshot(room):
    now = time.monotonic()
    return {"playing": room["playing"], "position": room["position"] + (now - room["at"] if room["playing"] else 0), "version": room["version"]}


class Handler(BaseHTTPRequestHandler):
    def reply(self, code, data):
        body = json.dumps(data, ensure_ascii=False).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(body)

    def do_POST(self):
        try:
            if int(self.headers.get("Content-Length", 0)) > 4096:
                return self.reply(413, {"error": "请求过大"})
            data = json.loads(self.rfile.read(int(self.headers.get("Content-Length", 0))))
            with lock:
                if self.path == "/api/create":
                    code = ''.join(secrets.choice('23456789ABCDEFGHJKLMNPQRSTUVWXYZ') for _ in range(6))
                    while code in rooms:
                        code = secrets.token_hex(3).upper()
                    rooms[code] = {"playing": False, "position": 0, "at": time.monotonic(), "version": 0}
                    return self.reply(200, {"code": code})
                code = str(data.get("code", "")).upper()
                if code not in rooms:
                    return self.reply(404, {"error": "房间不存在，请检查房间码；服务重启后需重新创建。"})
                room = rooms[code]
                if self.path == "/api/state":
                    return self.reply(200, snapshot(room))
                if self.path == "/api/control":
                    pos = data.get("position")
                    if not isinstance(pos, (float, int)) or not 0 <= pos <= 86400 or not isinstance(data.get("playing"), bool):
                        return self.reply(400, {"error": "无效的播放状态"})
                    room.update(position=pos, playing=data["playing"], at=time.monotonic(), version=room["version"] + 1)
                    return self.reply(200, snapshot(room))
                return self.reply(404, {"error": "接口不存在"})
        except (ValueError, TypeError):
            self.reply(400, {"error": "请求格式错误"})

    def do_GET(self):
        path = urlparse(self.path).path
        file = ROOT / ("inputs/演示.mp4" if path == "/video" else "index.html")
        if path not in ("/", "/index.html", "/video"):
            return self.reply(404, {"error": "页面不存在"})
        size = file.stat().st_size
        start, end = 0, size - 1
        partial = self.headers.get("Range")
        if partial:
            try:
                unit, bounds = partial.split("=")
                a, b = bounds.split("-")
                if unit != "bytes":
                    raise ValueError()
                start, end = (int(a), min(int(b) if b else size - 1, size - 1)) if a else (max(0, size - int(b)), size - 1)
                if not 0 <= start <= end < size:
                    raise ValueError()
            except ValueError:
                self.send_response(416)
                self.send_header("Content-Range", f"bytes */{size}")
                self.send_header("Content-Length", "0")
                self.end_headers()
                return
        self.send_response(206 if partial else 200)
        self.send_header("Content-Type", "video/mp4" if path == "/video" else "text/html; charset=utf-8")
        self.send_header("Accept-Ranges", "bytes")
        self.send_header("Content-Length", str(end - start + 1))
        self.send_header("Cache-Control", "no-store")
        if partial:
            self.send_header("Content-Range", f"bytes {start}-{end}/{size}")
        self.end_headers()
        try:
            with file.open("rb") as stream:
                stream.seek(start)
                remaining = end - start + 1
                while remaining:
                    block = stream.read(min(65536, remaining))
                    if not block:
                        break
                    self.wfile.write(block)
                    remaining -= len(block)
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            pass


if __name__ == "__main__":
    print("一起看已启动：http://127.0.0.1:8765 （关闭此窗口或按 Ctrl+C 停止）", flush=True)
    try:
        ThreadingHTTPServer(("127.0.0.1", 8765), Handler).serve_forever()
    except KeyboardInterrupt:
        pass

